      "ಆ ದಿನ ನಿಮ್ಮನ್ನು ದುಪ್ಪಟ್ಟು ತಾಳ್ಮೆ ಮತ್ತು ಪ್ರೀತಿಯಿಂದ ನೋಡಿಕೊಳ್ಳುವ ಭರವಸೆ ಇದೆ."
