      "ನೀವು ಇಲ್ಲದಿದ್ದರೂ ಸಹ, ನಾನು ನಿಮ್ಮ ಹೆಸರನ್ನು ಪೂರ್ಣ ಗೌರವ ಮತ್ತು ನಿಷ್ಠೆಯಿಂದ ತೆಗೆದುಕೊಳ್ಳುತ್ತೇನೆ."
