      "ಮುಂದಿನ ಪ್ರತಿ ಬೆಳಿಗ್ಗೆ ನಾನು ಹೇಗೆ ನಿಭಾಯಿಸಿದೆ ಎಂಬುದಕ್ಕೆ ಸಾಕ್ಷಿಯಾಗುತ್ತದೆ."
